#!/usr/bin/env python3
"""Materialize the reviewed SIOPE builder and tests as plain source files."""
from __future__ import annotations

import base64
import gzip
import hashlib
from pathlib import Path

ROOT = Path(__file__).resolve().parent
PAYLOADS = {
    "build_siope_history.py": (
        "034c286cdecf11f8387598936982b8554fc6e6a35ab51c5324305b2e12128d77",
        ""
    ),
    "test_siope_history_v160.py": (
        "7aa6a9cfcbf6ffc97e0bba40beb6319eab78831e54523fbf7790861c46062b65",
        ""
    ),
}

for filename, (expected_sha256, payload) in PAYLOADS.items():
    content = gzip.decompress(base64.b64decode(payload))
    actual = hashlib.sha256(content).hexdigest()
    if actual != expected_sha256:
        raise RuntimeError(f"Hash sorgente SIOPE errato per {filename}: {actual}")
    target = ROOT / filename
    target.write_bytes(content)
    print(f"Sorgente SIOPE materializzato: {target}")
